 const [newOpen,setNewOpen]=useState(false),[folderOpen,setFolderOpen]=useState(false),[mobile,setMobile]=useState(false),[query,setQuery]=useState(''),[filter,setFilter]=useState(''),[toast,setToast]=useState(''),[dark,setDark]=useState(()=>localStorage.getItem('lang-theme')==='dark');
 const [generating,setGenerating]=useState(false),[tab,setTab]=useState('summary');const toastTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
