function PageTitle({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:ReactNode}){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action}</div>;}
function Empty({icon,title,text,action}:{icon:ReactNode;title:string;text:string;action?:ReactNode}){return <div className="empty-state"><div>{icon}</div><h2>{title}</h2><p>{text}</p>{action}</div>;}
function LessonTile({lesson:l,onClick,label}:{lesson:LessonCard;onClick:()=>void;label?:string}){const pct=l.chapterCount?Math.round(l.completed.length/l.chapterCount*100):0;return <button className="lesson-tile" onClick={onClick}><div className="tile-top"><span className="file-icon">{l.kind==='youtube'?<Link size={21}/>:l.kind==='example'?<Brain size={22}/>:<FileText size={22}/>}</span><span className="pill">{l.isDemo?'CONTOH':l.ready?'SIAP BELAJAR':'DRAF'}</span><ArrowUpRight className="tile-arrow" size={17}/></div><span className="tile-folder">{l.folder||'Tanpa folder'}</span><h3>{l.title}</h3><p>{l.ready?`${l.chapterCount} bab · ${l.cardCount} flashcard`:'Materi tersimpan · Belum diproses AI'}</p><div className="tile-bottom"><div className="track"><i style={{width:`${pct}%`}}/></div><div><span>{label||`${pct}% dipelajari`}</span><span>{date(l.updated)}</span></div></div></button>;}
function FolderDialog({onClose,onSave}:{onClose:()=>void;onSave:(n:string)=>Promise<void>}){const [name,setName]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <Dialog title="Satu tempat untuk satu topik." onClose={onClose}><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{await onSave(name.trim());}catch(e){setError((e as Error).message);setBusy(false);}}}><label className="field">Nama folder<input required maxLength={60} value={name} onChange={e=>setName(e.target.value)} placeholder="Misalnya: Matematika diskrit"/></label>{error&&<div className="alert">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={onClose}>Batal</button><button className="primary" disabled={!name.trim()||busy}>{busy?<Spinner/>:<FolderPlus size={17}/>} Buat folder</button></div></form></Dialog>;}

function NewLesson({ai,folders,onClose,onCreated}:{ai:boolean;folders:string[];onClose:()=>void;onCreated:(id:string,make:boolean)=>Promise<void>}){
 const [mode,setMode]=useState('text'),[title,setTitle]=useState(''),[text,setText]=useState(''),[url,setUrl]=useState(''),[files,setFiles]=useState<File[]>([]),[folder,setFolder]=useState(''),[language,setLanguage]=useState('Indonesia'),[make,setMake]=useState(ai),[busy,setBusy]=useState(false),[error,setError]=useState(''),[recording,setRecording]=useState(false),[seconds,setSeconds]=useState(0),[drag,setDrag]=useState(false);
 const recorder=useRef<MediaRecorder|null>(null),stream=useRef<MediaStream|null>(null),fileInput=useRef<HTMLInputElement>(null),alive=useRef(true);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;if(recorder.current?.state==='recording')recorder.current.stop();stream.current?.getTracks().forEach(t=>t.stop());};},[]);
 useEffect(()=>{if(!recording)return;const timer=setInterval(()=>setSeconds(s=>s+1),1000);return()=>clearInterval(timer);},[recording]);
 function addFiles(incoming:File[]){setError('');if(files.length+incoming.length>5){setError('Maksimal 5 berkas per pelajaran.');return;}setFiles(old=>[...old,...incoming]);if(!title&&incoming.length)setTitle(incoming[0].name.replace(/\.[^.]+$/,''));}
 async function record(){try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Rekam membutuhkan HTTPS atau localhost dan izin mikrofon.');const media=await navigator.mediaDevices.getUserMedia({audio:true});stream.current=media;const mime=MediaRecorder.isTypeSupported('audio/webm')?'audio/webm':MediaRecorder.isTypeSupported('audio/mp4')?'audio/mp4':'';const r=new MediaRecorder(media,mime?{mimeType:mime}:undefined);recorder.current=r;const chunks:BlobPart[]=[];r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};r.onstop=()=>{media.getTracks().forEach(t=>t.stop());if(!alive.current)return;const ext=r.mimeType.includes('mp4')?'m4a':'webm';const f=new File(chunks,`Rekaman-${Date.now()}.${ext}`,{type:r.mimeType});setFiles(old=>[...old,f].slice(0,5));setTitle(t=>t||`Rekaman belajar ${new Date().toLocaleDateString('id-ID')}`);setRecording(false);};r.start();setSeconds(0);setRecording(true);}catch(e){setError((e as Error).message);}}
 async function submit(e:FormEvent){e.preventDefault();setError('');setBusy(true);try{const form=new FormData();form.set('title',title);form.set('folder',folder);form.set('language',language);form.set('text',text);form.set('youtube',mode==='youtube'?url:'');files.forEach(f=>form.append('files',f));const r=await api('/lessons',{method:'POST',body:form});await onCreated(r.id,make&&ai);}catch(e){setError((e as Error).message);setBusy(false);}}
 return <Dialog title="Apa yang ingin kamu pahami?" wide onClose={()=>{if(!busy)onClose();}}><form onSubmit={submit}><div className="input-tabs">{[{id:'text',label:'Teks / topik',icon:Pencil},{id:'file',label:'Unggah',icon:Upload},{id:'youtube',label:'YouTube',icon:Link},{id:'record',label:'Rekam',icon:Mic}].map(m=><button key={m.id} type="button" className={mode===m.id?'active':''} onClick={()=>setMode(m.id)}><m.icon size={16}/>{m.label}</button>)}</div>
 <label className="field">Judul pelajaran<input required maxLength={160} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Misalnya: Memahami integral dari dasar" disabled={busy}/></label>
 {mode==='text'&&<label className="field">Materi atau topik<textarea rows={7} value={text} maxLength={150000} onChange={e=>setText(e.target.value)} placeholder="Tempel catatanmu di sini. Untuk belajar dari topik, cukup isi judul pelajaran." disabled={busy}/><small>Materi disimpan utuh. Maksimal 150.000 karakter per pelajaran.</small></label>}
 {mode==='file'&&<><input ref={fileInput} type="file" hidden multiple accept=".pdf,.docx,.pptx,.xlsx,.txt,.md,.csv,.jpg,.jpeg,.png,.webp,.mp3,.wav,.m4a,.ogg,.weba,.mp4,.mov,.webm,.avi,.mkv" onChange={e=>{addFiles(Array.from(e.target.files||[]));e.target.value='';}}/><button type="button" className={`dropzone ${drag?'dragging':''}`} onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);addFiles(Array.from(e.dataTransfer.files));}} onClick={()=>fileInput.current?.click()} disabled={busy}><Upload size={28} strokeWidth={1}/><strong>Taruh materimu di sini.</strong><span>Atau klik untuk memilih berkas</span><small>PDF, Office modern, teks, gambar, audio, video · maks. 5 berkas</small></button><p className="fine-print">Dokumen 100 MB · Gambar 25 MB · Audio 300 MB · Video 500 MB. OCR gambar dan transkripsi membutuhkan AI. PDF scan: unggah sebagai gambar.</p></>}
 {mode==='youtube'&&<label className="field">Tautan video YouTube<input type="url" required value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://www.youtube.com/watch?v=…" disabled={busy}/><small>Video harus memiliki transkrip yang dapat diakses. Jika gagal, tempel transkrip melalui tab Teks.</small></label>}
 {mode==='record'&&<div className="record-box"><Mic size={32} strokeWidth={1}/><h3>{recording?'Sedang mendengarkan…':'Tangkap ide sebelum terlupa.'}</h3><p>{recording?`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:'Rekam penjelasan atau sesi belajarmu.'}</p><button type="button" className={recording?'primary':'secondary'} disabled={busy||files.length>=5} onClick={recording?()=>recorder.current?.stop():record}>{recording?<Square size={15}/>:<Mic size={15}/>} {recording?'Selesai merekam':'Mulai rekam'}</button><small>Transkripsi memerlukan API aktif dan FFmpeg di server.</small></div>}
 {files.length>0&&<div className="selected-files">{files.map((f,i)=><div key={`${f.name}-${i}`}><FileText size={16}/><span>{f.name}<small>{(f.size/1024/1024).toFixed(1)} MB</small></span><button type="button" className="icon-button" aria-label={`Hapus ${f.name}`} disabled={busy} onClick={()=>setFiles(fs=>fs.filter((_,j)=>j!==i))}><X size={16}/></button></div>)}</div>}
 <div className="field-row"><label className="field">Folder<select value={folder} onChange={e=>setFolder(e.target.value)}><option value="">Tanpa folder</option>{folders.map(f=><option key={f}>{f}</option>)}</select></label><label className="field">Bahasa pelajaran<select value={language} onChange={e=>setLanguage(e.target.value)}>{['Indonesia','English','العربية','中文'].map(l=><option key={l}>{l}</option>)}</select></label></div>
 {ai?<label className="checkbox"><input type="checkbox" checked={make} onChange={e=>setMake(e.target.checked)}/>Langsung buat ringkasan, bab, flashcard, dan soal dengan AI.</label>:<div className="subtle-note"><InfoIcon/>AI belum terhubung. Teks dan dokumen akan disimpan sebagai draf.</div>}
 {error&&<div className="alert" role="alert">{error}</div>}
 <div className="dialog-actions"><button className="secondary" type="button" onClick={onClose} disabled={busy}>Batal</button><button className="primary" disabled={busy||recording||!title.trim()}>{busy?<Spinner/>:<ArrowRight size={17}/>} {busy?'Membaca & menyimpan materi…':make&&ai?'Buat pelajaran':'Simpan draf'}</button></div></form></Dialog>;
}
function InfoIcon(){return <AlertCircle size={17}/>;}

function LessonView({lesson:l,tab,setTab,onBack,reload,notify,ai,generating,onGenerate,onDelete,folders}:{lesson:Lesson;tab:string;setTab:(t:string)=>void;onBack:()=>void;reload:()=>Promise<void>;notify:(s:string)=>void;ai:boolean;generating:boolean;onGenerate:()=>Promise<void>;onDelete:()=>Promise<void>;folders:string[]}){
 const [chapter,setChapter]=useState(0),[edit,setEdit]=useState(false),[source,setSource]=useState(false),[marking,setMarking]=useState(false);
 const tabs=[{id:'summary',label:'Ringkasan',icon:FileText},{id:'learn',label:'Belajar',icon:BookOpen},{id:'map',label:'Mind map',icon:Network},{id:'cards',label:'Flashcard',icon:Layers},{id:'quiz',label:'Kuis',icon:Brain},{id:'exam',label:'Ujian',icon:GraduationCap},{id:'chat',label:'Tutor AI',icon:Sparkles}];
 const ready=!!l.content;
 return <div className="lesson-view"><button className="text-button back-button" onClick={onBack}><ArrowLeft size={15}/> Kembali ke ruang belajar</button><div className="lesson-heading"><div><div className="eyebrow"><Folder size={13}/>{l.folder||'TANPA FOLDER'}<span>/</span>{l.isDemo?'MATERI CONTOH':l.language.toUpperCase()}</div><h1>{l.title}</h1><p>{ready?`${l.content!.chapters.length} bab · ${l.content!.flashcards.length} flashcard · ${l.completed.length} bab selesai`:'Draf tersimpan · Siap diolah menjadi pelajaran'}</p></div><div className="lesson-actions"><button className="icon-button bordered" title="Sunting pelajaran" aria-label="Sunting pelajaran" onClick={()=>setEdit(true)}><Pencil size={17}/></button><button className="icon-button bordered" title="Lihat sumber" aria-label="Lihat sumber" onClick={()=>setSource(true)}><FileText size={17}/></button><button className="icon-button bordered" title="Unduh catatan" aria-label="Unduh catatan" onClick={()=>{const body=`# ${l.title}\n\n${l.content?.summary||l.sourceText}\n\n${l.content?.chapters.map(c=>`## ${c.title}\n\n${c.body}`).join('\n\n')||''}`;download(`${l.title.replace(/[^\p{L}\p{N} -]/gu,'').slice(0,80)||'catatan'}.md`,body,'text/markdown');}}><Download size={17}/></button><button className="icon-button bordered danger" title="Hapus pelajaran" aria-label="Hapus pelajaran" onClick={onDelete} disabled={generating}><Trash2 size={17}/></button></div></div>
 {generating&&<div className="generating" role="status"><Spinner/><div><strong>Menyusun pelajaranmu…</strong><p>AI sedang menyiapkan bab, kartu, dan soal. Draf sumber tetap tersimpan.</p></div></div>}
 <div className="lesson-tabs" role="tablist" aria-label="Alat belajar">{tabs.map(t=><button key={t.id} role="tab" aria-selected={tab===t.id} onClick={()=>setTab(t.id)} className={tab===t.id?'active':''}><t.icon size={16}/>{t.label}</button>)}</div>
 {!ready&&tab!=='chat'?<div className="draft-layout"><div className="draft-card"><span className="eyebrow">LANGKAH PERTAMA SUDAH SELESAI</span><h2>Materimu sudah punya tempat.</h2><p>Ubah draf ini menjadi ringkasan, bab belajar, mind map, flashcard, kuis, dan latihan ujian.</p><button className="primary" disabled={!ai||generating} onClick={onGenerate}>{generating?<Spinner/>:<Sparkles size={17}/>} Susun dengan AI</button>{!ai&&<small>Isi OPENAI_API_KEY di .env server untuk mengaktifkan AI.</small>}</div><div className="reader source-preview"><span className="eyebrow">SUMBER MATERI</span>{l.sourceText?<pre>{l.sourceText}</pre>:<p>Topik: {l.title}. Pelajaran akan disusun dari pengetahuan umum AI.</p>}</div></div>:<>
 {tab==='summary'&&l.content&&<div className="reader-layout"><article className="reader"><div className="reader-label"><span className="eyebrow">INTI YANG PERLU KAMU INGAT</span><button className="icon-button" aria-label="Edit ringkasan" onClick={()=>setEdit(true)}><Pencil size={15}/></button></div>{md(l.content.summary)}<div className="reader-end"><span>Sudah mendapat gambaran besarnya?</span><button className="primary" onClick={()=>setTab('learn')}>Pelajari per bab <ArrowRight size={16}/></button></div></article><aside className="study-aside"><div className="aside-card"><BookOpen size={23} strokeWidth={1.2}/><h3>Pahami satu per satu.</h3><p>Pelajaran ini terbagi menjadi {l.content.chapters.length} bab kecil. Mulai dari mana pun kamu perlu.</p>{l.content.chapters.map((c,i)=><button key={i} onClick={()=>{setChapter(i);setTab('learn');}}><span>{l.completed.includes(i)?<Check size={14}/>:String(i+1).padStart(2,'0')}</span>{c.title}<ChevronRight size={14}/></button>)}</div><div className="aside-note"><Sparkles size={20}/><h3>Ada yang belum jelas?</h3><p>Tanyakan pada tutor yang membaca materimu.</p><button className="text-button" onClick={()=>setTab('chat')}>Buka tutor <ArrowUpRight size={15}/></button></div>{ai&&<button className="text-button regenerate" disabled={generating} onClick={()=>{if(confirm('Buat ulang pelajaran? Catatan hasil AI, progres bab, dan jadwal kartu saat ini akan diganti.'))onGenerate();}}><RotateCcw size={14}/> Buat ulang pelajaran</button>}</aside></div>}
 {tab==='learn'&&l.content&&<div className="chapter-layout"><aside className="chapter-nav"><span className="eyebrow">DAFTAR BAB</span>{l.content.chapters.map((c,i)=><button key={i} className={chapter===i?'active':''} onClick={()=>setChapter(i)}><span>{l.completed.includes(i)?<Check size={15}/>:String(i+1).padStart(2,'0')}</span>{c.title}</button>)}<div className="track"><i style={{width:`${l.completed.length/l.content.chapters.length*100}%`}}/></div><small>{l.completed.length} dari {l.content.chapters.length} bab selesai</small></aside><article className="reader"><span className="eyebrow">BAB {String(chapter+1).padStart(2,'0')} / {String(l.content.chapters.length).padStart(2,'0')}</span>{md(l.content.chapters[chapter]?.body||'Pilih bab untuk mulai.')}<div className="reader-end"><button className="secondary" disabled={chapter===0} onClick={()=>setChapter(c=>c-1)}><ArrowLeft size={15}/> Sebelumnya</button><button className="primary" disabled={marking} onClick={async()=>{setMarking(true);try{await post(`/lessons/${l.id}/chapter`,{index:chapter});await reload();if(chapter<l.content!.chapters.length-1)setChapter(c=>c+1);else{notify('Semua bab selesai. Saatnya menguji pemahamanmu.');setTab('quiz');}}catch(e){notify((e as Error).message);}finally{setMarking(false);}}}>{marking?<Spinner/>:<CheckCheck size={16}/>} {chapter===l.content.chapters.length-1?'Selesai & latihan':'Paham, lanjut'}</button></div></article></div>}
 {tab==='map'&&l.content&&<div className="map-board"><span className="eyebrow">LIHAT HUBUNGAN ANTARIDE</span><h2>{l.title}</h2><div className="map-root"><Network size={20}/>Gambaran besar</div><div className="map-branches">{l.content.mindmap.map((m,i)=><div className="map-branch" key={i}><span>{String(i+1).padStart(2,'0')}</span><h3>{m.topic}</h3><ul>{m.points.map((p,j)=><li key={j}>{p}</li>)}</ul></div>)}</div><p className="fine-print">Gunakan peta ini untuk menghubungkan konsep sebelum masuk ke detail.</p></div>}
 {tab==='cards'&&l.content&&<Flashcards key={l.id} lesson={l} reload={reload} notify={notify}/>}
 {(tab==='quiz'||tab==='exam')&&l.content&&<Quiz key={`${l.id}-${tab}`} lesson={l} mode={tab} reload={reload} notify={notify}/>}
 {tab==='chat'&&<Chat key={l.id} lesson={l} ai={ai} reload={reload}/>}
 </>}
 {edit&&<EditLesson lesson={l} folders={folders} onClose={()=>setEdit(false)} onSave={async p=>{await api(`/lessons/${l.id}`,{method:'PATCH',body:JSON.stringify(p)});await reload();setEdit(false);notify('Perubahan disimpan.');}}/>}
 {source&&<Dialog title="Sumber pelajaran" wide onClose={()=>setSource(false)}><div className="source-files">{l.files.map((f,i)=><a key={i} href={`/api/lessons/${l.id}/files/${i}`} className="secondary" download><FileText size={16}/>{f.name}<Download size={15}/></a>)}</div><pre className="source-text">{l.sourceText||`Pelajaran dari topik: ${l.title}`}</pre><p className="fine-print">Sumber ini digunakan sebagai konteks tutor dan pembuatan pelajaran.</p></Dialog>}
 </div>;
}
function download(name:string,text:string,mime='application/json'){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function EditLesson({lesson,folders,onClose,onSave}:{lesson:Lesson;folders:string[];onClose:()=>void;onSave:(p:unknown)=>Promise<void>}){const [title,setTitle]=useState(lesson.title),[folder,setFolder]=useState(lesson.folder),[summary,setSummary]=useState(lesson.content?.summary||''),[source,setSource]=useState(lesson.sourceText),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <Dialog title="Rapikan catatanmu." wide onClose={()=>{if(!busy)onClose();}}><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{await onSave({title,folder,...(lesson.content?{summary}:{sourceText:source})});}catch(e){setError((e as Error).message);setBusy(false);}}}><label className="field">Judul<input required maxLength={160} value={title} onChange={e=>setTitle(e.target.value)}/></label><label className="field">Folder<select value={folder} onChange={e=>setFolder(e.target.value)}><option value="">Tanpa folder</option>{folders.map(f=><option key={f}>{f}</option>)}</select></label><label className="field">{lesson.content?'Ringkasan (Markdown)':'Sumber materi'}<textarea rows={12} maxLength={lesson.content?30000:150000} value={lesson.content?summary:source} onChange={e=>lesson.content?setSummary(e.target.value):setSource(e.target.value)}/></label>{error&&<div className="alert">{error}</div>}<div className="dialog-actions"><button className="primary" disabled={busy}>{busy?<Spinner/>:<Check size={16}/>} Simpan perubahan</button></div></form></Dialog>;}

function Flashcards({lesson:l,reload,notify}:{lesson:Lesson;reload:()=>Promise<void>;notify:(s:string)=>void}){
 const [flipped,setFlipped]=useState(false),[busy,setBusy]=useState(false),[reviewed,setReviewed]=useState(0),[all,setAll]=useState(false),[now,setNow]=useState(Date.now());
 useEffect(()=>{const t=setInterval(()=>setNow(Date.now()),30000);return()=>clearInterval(t);},[]);
 const cards=l.content!.flashcards;const due=cards.map((c,i)=>({...c,i})).filter(c=>!l.reviews[c.i]||l.reviews[c.i].due<=now);const current=due[0];
 async function rate(rating:string){if(!current||busy)return;setBusy(true);try{await post(`/lessons/${l.id}/review`,{card:current.i,rating});await reload();setFlipped(false);setReviewed(n=>n+1);setNow(Date.now());}catch(e){notify((e as Error).message);}finally{setBusy(false);}}
 const rateRef=useRef(rate);rateRef.current=rate;
 useEffect(()=>{const key=(e:KeyboardEvent)=>{if((e.target as HTMLElement).matches('input,textarea,select')||all)return;if(e.code==='Space'&&!(e.target as HTMLElement).closest('button')){e.preventDefault();setFlipped(f=>!f);}if(flipped&&['1','2','3','4'].includes(e.key)){e.preventDefault();rateRef.current(['again','hard','good','easy'][Number(e.key)-1]);}};document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key);},[flipped,all]);
 return <section className="flashcard-section"><div className="practice-top"><span className="eyebrow">{due.length} KARTU JATUH TEMPO · {reviewed} SELESAI SESI INI</span><button className="text-button" onClick={()=>setAll(!all)}>{all?'Kembali review':'Semua kartu'} <Layers size={15}/></button></div>{all?<div className="all-cards">{cards.map((c,i)=><div key={i}><span className="eyebrow">KARTU {i+1}</span><h3>{c.front}</h3>{md(c.back)}<small>{l.reviews[i]?`Review berikutnya: ${new Date(l.reviews[i].due).toLocaleString('id-ID')}`:'Belum dipelajari'}</small></div>)}</div>:current?<><button className={`flashcard ${flipped?'flipped':''}`} onClick={()=>setFlipped(!flipped)} aria-label={flipped?'Lihat pertanyaan':'Balik kartu untuk melihat jawaban'}><span className="eyebrow">{flipped?'JAWABAN':'COBA INGAT DULU'}</span><span className="card-number">{String(current.i+1).padStart(2,'0')} / {cards.length}</span><span className="flashcard-content">{flipped?current.back:current.front}</span><span className="flip-hint"><RotateCcw size={15}/>{flipped?'Klik untuk kembali ke pertanyaan':'Klik kartu untuk membuka jawaban'}</span></button><div className="card-rating">{flipped?<><p>Seberapa mudah kamu mengingatnya?</p><div>{[{id:'again',label:'Lagi',hint:'1 menit'},{id:'hard',label:'Sulit',hint:'Jeda pendek'},{id:'good',label:'Bagus',hint:'≥ 1 hari'},{id:'easy',label:'Mudah',hint:'≥ 4 hari'}].map((r,i)=><button key={r.id} disabled={busy} className={r.id==='good'?'primary':'secondary'} onClick={()=>rate(r.id)}><span><kbd>{i+1}</kbd>{r.label}</span><small>{r.hint}</small></button>)}</div></>:<p>Usahakan menjawab sebelum membalik. Tidak perlu sempurna.</p>}</div></>:<Empty icon={<CheckCheck size={40}/>} title="Ingatanmu boleh istirahat." text="Semua kartu sudah terjadwal. Kartu yang sulit akan kembali lebih cepat; kartu yang mudah mendapat jeda lebih panjang." action={<button className="secondary" onClick={()=>setAll(true)}>Lihat semua kartu</button>}/>}</section>;
}

function Quiz({lesson:l,mode,reload,notify}:{lesson:Lesson;mode:'quiz'|'exam';reload:()=>Promise<void>;notify:(s:string)=>void}){
 const qs=l.content![mode];const [started,setStarted]=useState(false),[index,setIndex]=useState(0),[answers,setAnswers]=useState<number[]>(Array(qs.length).fill(-1)),[checked,setChecked]=useState<Set<number>>(new Set()),[result,setResult]=useState<Result|null>(null),[busy,setBusy]=useState(false),[seconds,setSeconds]=useState(0);const requestId=useRef(crypto.randomUUID());
 useEffect(()=>{if(!started||result)return;const t=setInterval(()=>setSeconds(n=>n+1),1000);return()=>clearInterval(t);},[started,result]);
 async function submit(){setBusy(true);try{const r=await post<Result>(`/lessons/${l.id}/attempt`,{mode,answers,requestId:requestId.current});setResult(r);await reload();}catch(e){notify((e as Error).message);}finally{setBusy(false);}}
 function reset(){setStarted(false);setIndex(0);setAnswers(Array(qs.length).fill(-1));setChecked(new Set());setResult(null);setSeconds(0);requestId.current=crypto.randomUUID();}
 if(result)return <div className="results"><div className="result-hero"><span className="eyebrow">SELESAI. SATU LANGKAH LEBIH PAHAM.</span><div className="score-circle"><strong>{result.score}</strong><span>DARI 100</span></div><h2>{result.score>=80?'Pemahamanmu semakin kuat.':'Sekarang kamu tahu bagian yang perlu diulang.'}</h2><p>{result.correct} dari {result.total} jawaban benar · {Math.floor(seconds/60)} menit {seconds%60} detik</p><button className="secondary" onClick={reset}><RotateCcw size={16}/> Latihan lagi</button></div><h3>Pembahasan jawaban</h3>{result.results.map((q,i)=><article className="answer-review" key={i}><div><span className={`answer-badge ${q.correct?'correct':''}`}>{q.correct?<Check size={15}/>:<X size={15}/>}</span><h3>{i+1}. {q.question}</h3></div><p>Jawabanmu: <strong>{q.options[q.selected]}</strong></p>{!q.correct&&<p>Jawaban benar: <strong>{q.options[q.answer]}</strong></p>}{md(q.explanation)}</article>)}</div>;
 if(!started)return <div className="quiz-intro"><div className="large-icon">{mode==='exam'?<GraduationCap size={39} strokeWidth={1}/>:<Brain size={39} strokeWidth={1}/>}</div><span className="eyebrow">{mode==='exam'?'SIMULASI BELAJAR MANDIRI':'DARI MEMBACA KE MEMAHAMI'}</span><h2>{mode==='exam'?'Siap menguji diri sendiri?':'Seberapa jauh kamu paham?'}</h2><p>{mode==='exam'?'Kerjakan tanpa membuka catatan. Jawaban dan pembahasan ditampilkan setelah semua soal dikumpulkan.':'Jawab soal satu per satu. Kamu bisa memeriksa jawaban dan membaca penjelasan sebelum lanjut.'}</p><div className="quiz-facts"><span><FileText size={16}/>{qs.length} soal pilihan ganda</span><span><Clock size={16}/>Tanpa batas waktu</span></div><button className="primary" onClick={()=>setStarted(true)}>Mulai {mode==='exam'?'ujian':'kuis'} <ArrowRight size={17}/></button></div>;
 const q=qs[index],isChecked=checked.has(index);const count=answers.filter(a=>a>=0).length;
 return <div className="quiz-session"><div className="practice-top"><span className="eyebrow">SOAL {index+1} DARI {qs.length}</span><span className="timer"><Clock size={14}/>{Math.floor(seconds/60)}:{String(seconds%60).padStart(2,'0')}</span></div><div className="track quiz-track"><i style={{width:`${count/qs.length*100}%`}}/></div><div className="question-dots">{qs.map((_,i)=><button key={i} aria-label={`Ke soal ${i+1}`} aria-current={index===i?'step':undefined} className={`${index===i?'current':''} ${answers[i]>=0?'answered':''}`} onClick={()=>setIndex(i)}>{i+1}</button>)}</div><h2>{q.question}</h2><div className="options" role="radiogroup" aria-label="Pilihan jawaban">{q.options.map((o,i)=><button key={i} role="radio" aria-checked={answers[index]===i} disabled={isChecked&&mode==='quiz'} className={`${answers[index]===i?'selected':''} ${isChecked&&mode==='quiz'?(q.answer===i?'correct':answers[index]===i?'incorrect':''):''}`} onClick={()=>setAnswers(a=>a.map((v,j)=>j===index?i:v))}><span>{String.fromCharCode(65+i)}</span><div>{o}</div>{answers[index]===i&&<Check size={17}/>}</button>)}</div>{isChecked&&mode==='quiz'&&<div className="feedback"><strong>{answers[index]===q.answer?'Tepat sekali.':'Belum tepat. Mari pahami alasannya.'}</strong>{md(q.explanation)}</div>}<div className="quiz-controls"><button className="secondary" disabled={index===0} onClick={()=>setIndex(i=>i-1)}><ArrowLeft size={15}/>Sebelumnya</button>{mode==='quiz'&&!isChecked?<button className="primary" disabled={answers[index]<0} onClick={()=>setChecked(old=>new Set([...old,index]))}>Periksa jawaban <Check size={16}/></button>:index<qs.length-1?<button className="primary" onClick={()=>setIndex(i=>i+1)}>Berikutnya <ArrowRight size={16}/></button>:<button className="primary" disabled={count<qs.length||busy} onClick={submit}>{busy?<Spinner/>:<CheckCheck size={16}/>} Kumpulkan ({count}/{qs.length})</button>}</div></div>;
}

function Chat({lesson:l,ai,reload}:{lesson:Lesson;ai:boolean;reload:()=>Promise<void>}){const [text,setText]=useState(''),[messages,setMessages]=useState(l.chats),[busy,setBusy]=useState(false),[error,setError]=useState('');const end=useRef<HTMLDivElement>(null);useEffect(()=>end.current?.scrollIntoView({behavior:'smooth',block:'nearest'}),[messages,busy]);async function send(value:string){if(!value.trim()||busy)return;setError('');setBusy(true);try{const r=await post(`/lessons/${l.id}/chat`,{message:value});setMessages(old=>[...old,{role:'user',content:value},{role:'assistant',content:r.reply}]);setText('');await reload();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}return <div className="chat-layout"><div className="chat-context"><Sparkles size={21}/><div><strong>Tutor belajarmu</strong><small>Mengacu pada: {l.title}</small></div><span className="pill">{ai?'TERHUBUNG':'BELUM TERHUBUNG'}</span></div><div className="chat-messages">{!messages.length&&<div className="chat-welcome"><div className="tutor-mark">l_</div><h2>Bagian mana yang masih<br/>membuatmu penasaran?</h2><p>Aku bisa menjelaskan konsep, memberi contoh,<br/>atau membantumu berpikir langkah demi langkah.</p><div className="suggestions">{['Jelaskan konsep utama dengan bahasa sederhana.','Beri contoh penerapan dalam kehidupan sehari-hari.','Bantu aku memahami bagian yang paling sulit.'].map(s=><button key={s} disabled={!ai} onClick={()=>send(s)}>{s}<ArrowUpRight size={15}/></button>)}</div></div>}{messages.map((m,i)=><div key={i} className={`message ${m.role}`}><span>{m.role==='user'?'KAMU':'TUTOR'}</span>{md(m.content)}</div>)}{busy&&<div className="message assistant"><Spinner/><span>Tutor sedang menyusun penjelasan…</span></div>}<div ref={end}/></div>{error&&<div className="alert" role="alert">{error}</div>}{!ai&&<div className="subtle-note"><Lock size={16}/>Tutor aktif setelah OPENAI_API_KEY diisi pada server. Tidak ada jawaban AI simulasi.</div>}<form className="chat-input" onSubmit={e=>{e.preventDefault();send(text);}}><textarea aria-label="Pertanyaan untuk tutor" value={text} onChange={e=>setText(e.target.value)} placeholder="Tanyakan tentang materimu…" rows={2} maxLength={4000} disabled={!ai||busy} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(text);}}}/><button className="primary" disabled={!ai||busy||!text.trim()} aria-label="Kirim pertanyaan">{busy?<Spinner/>:<Send size={18}/>}</button></form><p className="fine-print center">AI bisa keliru. Cocokkan penjelasan penting dengan sumber materimu.</p></div>;}

function Progress({data}:{data:Dashboard}){const days=Array.from({length:7},(_,i)=>{const d=Date.now()-(6-i)*86400000;const key=day(d);return {label:new Intl.DateTimeFormat('id-ID',{weekday:'short',timeZone:'Asia/Jakarta'}).format(d),xp:data.events.filter(e=>e.day===key).reduce((s,e)=>s+e.xp,0),date:key};});const max=Math.max(30,...days.map(d=>d.xp));return <><PageTitle eyebrow="BUKAN PERLOMBAAN" title="Lihat seberapa jauh kamu melangkah." description="Kemajuan kecil yang dilakukan terus-menerus akan terasa besar."/><div className="progress-stats">{[{label:'Streak sekarang',value:`${data.stats.streak} hari`,icon:Flame},{label:'Total pengalaman',value:`${data.stats.xp} XP`,icon:Target},{label:'Level belajar',value:String(data.stats.level).padStart(2,'0'),icon:ChartNoAxesCombined},{label:'Bab diselesaikan',value:String(data.lessons.reduce((s,l)=>s+l.completed.length,0)),icon:CheckCheck}].map(s=><div key={s.label}><s.icon size={21}/><span>{s.label}</span><strong>{s.value}</strong></div>)}</div><div className="progress-panels"><section className="panel"><div className="section-heading"><div><span className="eyebrow">7 HARI TERAKHIR</span><h3>Ritme belajarmu</h3></div><span className="pill">WIB</span></div><div className="bar-chart" role="img" aria-label={days.map(d=>`${d.date}: ${d.xp} XP`).join(', ')}>{days.map(d=><div key={d.date}><span>{d.xp}</span><div className="bar-well"><i style={{height:`${d.xp/max*100}%`}}/></div><small>{d.label}</small></div>)}</div><p className="fine-print">XP berasal dari materi, bab, review kartu, dan latihan yang kamu selesaikan.</p></section><section className="panel activity"><span className="eyebrow">JEJAK KECILMU</span><h3>Aktivitas terakhir</h3>{data.events.length?data.events.slice(0,6).map(e=><div key={e.id}><span className="activity-dot"/><div><strong>{e.label}</strong><small>{date(e.created)}</small></div><span>+{e.xp}</span></div>):<p className="muted">Belum ada aktivitas. Satu pelajaran cukup untuk memulai.</p>}</section></div><section className="panel attempts"><div className="section-heading"><div><span className="eyebrow">BELAJAR DARI SETIAP PERCOBAAN</span><h3>Riwayat latihan</h3></div></div>{data.attempts.length?<div className="table-scroll"><table><thead><tr><th>Pelajaran</th><th>Jenis</th><th>Tanggal</th><th>Nilai</th></tr></thead><tbody>{data.attempts.map(a=><tr key={a.id}><td>{a.title}</td><td>{a.mode==='exam'?'Ujian':'Kuis'}</td><td>{date(a.created)}</td><td><strong>{a.score}/100</strong></td></tr>)}</tbody></table></div>:<p className="muted">Hasil kuis dan latihan ujianmu akan tercatat di sini.</p>}</section></>;}

function SettingsPage({status,dark,setDark,refresh,notify,onLogout}:{status:{aiConfigured:boolean;model:string;storage:string;timezone:string};dark:boolean;setDark:(v:boolean)=>void;refresh:()=>Promise<void>;notify:(s:string)=>void;onLogout:()=>Promise<void>}){const [checking,setChecking]=useState(false);return <><PageTitle eyebrow="SESUAIKAN RUANGMU" title="Hal-hal di balik layar." description="Preferensi, koneksi AI, dan data belajarmu."/><div className="settings-grid"><section className="panel"><div className="settings-title"><Sparkles size={22}/><h3>Koneksi AI</h3><span className="pill">{status.aiConfigured?'KEY TERPASANG':'BELUM TERHUBUNG'}</span></div><p>API key disimpan hanya di server. Kolom konfigurasi key sengaja dibiarkan kosong.</p><div className="config-block"><code>OPENAI_API_KEY=</code><code>OPENAI_MODEL={status.model}</code></div><ol><li>Salin <code>.env.example</code> menjadi <code>.env</code> pada server.</li><li>Isi <code>OPENAI_API_KEY</code> dengan key milikmu.</li><li>Mulai ulang server, lalu periksa status di bawah.</li></ol><button className="secondary" disabled={checking} onClick={async()=>{setChecking(true);try{await refresh();notify('Status konfigurasi diperbarui. Koneksi API diuji saat membuat pelajaran atau bertanya.');}catch(e){notify((e as Error).message);}finally{setChecking(false);}}}>{checking?<Spinner/>:<RotateCcw size={15}/>} Periksa konfigurasi</button><p className="fine-print">Status key terpasang tidak menjamin saldo atau izin model. Penggunaan API mengikuti akun API milikmu.</p></section><section className="panel"><div className="settings-title"><Sun size={22}/><h3>Tampilan</h3></div><p>Monokrom. Sedikit distraksi. Lebih banyak ruang untuk berpikir.</p><div className="theme-options"><button className={!dark?'selected':''} onClick={()=>setDark(false)}><Sun size={22}/>Terang<span className="theme-preview light"/></button><button className={dark?'selected':''} onClick={()=>setDark(true)}><Moon size={22}/>Gelap<span className="theme-preview dark"/></button></div><div className="setting-row"><span>Tipografi</span><strong>IBM Plex Mono</strong></div><div className="setting-row"><span>Zona waktu progres</span><strong>Asia/Jakarta</strong></div></section><section className="panel"><div className="settings-title"><Download size={22}/><h3>Data tetap milikmu</h3></div><p>Pelajaran, chat, jadwal kartu, dan riwayat tersimpan di database server. Ekspor data untuk salinan cadangan.</p><a className="secondary inline" href="/api/export" download><Download size={16}/> Ekspor data JSON</a><p className="fine-print">Ekspor JSON berisi teks dan progres. Untuk cadangan lengkap termasuk berkas asli, salin folder data/ saat server berhenti.</p></section><section className="panel"><div className="settings-title"><HelpCircle size={22}/><h3>Cara menggunakan Lang</h3></div><ol><li>Tambahkan materi atau coba pelajaran contoh.</li><li>Baca ringkasan dan pelajari bab.</li><li>Ulangi kartu dan kerjakan latihan.</li><li>Tanyakan konsep yang sulit kepada tutor AI.</li></ol><p className="fine-print">DOC/PPT/XLS lama dan HEIC perlu dikonversi. Audio/video memerlukan FFmpeg. YouTube bergantung pada ketersediaan transkrip.</p><button className="text-button" onClick={onLogout}><LogOut size={15}/> Keluar dari sesi</button></section></div></>;}
function Login({onLogin}:{onLogin:()=>void}){const [password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');return <div className="login-page"><div className="login-card"><span className="logo">lang_</span><span className="eyebrow">RUANG BELAJAR PRIBADIMU</span><h1>Selamat datang<br/>kembali.</h1><p>Satu langkah kecil lagi untuk memahami sesuatu yang baru.</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{await post('/login',{password});onLogin();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><label className="field">Password ruang belajar<input type="password" required autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)}/></label>{error&&<div className="alert">{error}</div>}<button className="primary" disabled={busy}>{busy?<Spinner/>:<ArrowRight size={17}/>} Masuk ke ruang belajar</button></form></div></div>;}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
